  topologyRoutingHelp: "ஒவ்வொரு கிளையன்ட்டின் கேபிளும் ஒரு குழுவுக்குச் செல்லும். குழு தன் வரிசைகளை — சந்தாக்களின் மாதிரிகள், செல்கள் — மேலிருந்து கீழாக முயற்சிக்கும். குழுக்கள் ரூட்டிங்கில் உருவாக்கப்படுகின்றன.",
