  poolSwitchHandle: "மாற்ற நிலை: இந்த வரம்பில் மீதமுள்ள எந்தப் பங்கிலிருந்து குழு கோரிக்கைகளை முதலில் தனது அடுத்த படிகளுக்கு அனுப்புமோ, அந்தப் பங்குக்கு இழுக்கவும். அவற்றில் எதுவும் சேவை வழங்க முடியாதபோது, இந்தப் படி இன்னும் சேவை வழங்கும்.",
