  poolChatOnly: "அரட்டை மட்டும்",
  poolWindowHint: "ஒரு கோரிக்கையில் குழு தன் கிளையன்ட்களுக்கு உறுதியளிக்கும் டோக்கன்கள். இங்கே குறிப்பிட்டபடியே வெளியிடப்படும்; கீழுள்ள நிலைமாற்றி அணைந்திருக்கும் வரை இதற்குப் பதிலாக எதுவும் எடுக்கப்படாது.",
  poolWindowAuto: "படிகளின் மாடல்கள் தெரிவிக்கும் மிகச் சிறிய சாளரத்தைப் பயன்படுத்து",
  poolWindowAutoHint: "அணைப்பு: நீங்கள் குறிப்பிட்ட எண் மட்டுமே வெளியிடப்படும். இயக்கம்: இயக்கப்பட்ட படிகளின் மாடல்களுக்கு வழங்குநர்கள் தெரிவிக்கும் மிகச் சிறிய சாளரம், அதனால் கோரிக்கை ஒவ்வொரு படிக்கும் பொருந்தும்.",
  rtPoolNoStep: "சேவை செய்யக்கூடிய படி எதுவும் இல்லை: கோரிக்கைகள் நிராகரிக்கப்படும்",
