  runnerPrism: "PrismML",
  runnerPrismBenefits: "Bonsai GGUF (PQ2_0/PTQ1_0) க்கான PrismML கிளை. முதல் தொடக்கத்தில் தனி இயக்கச் சூழல் நிறுவப்படும்.",
  runnerPrismMinus: "புதுப்பிக்கப்பட்ட scout மற்றும் தனியான நிலையான PrismML பதிப்பு தேவை.",
