  llamaErrUnsupportedQuantHint: "இந்த GGUF ஐ ஆதரிக்கும் இயக்கச் சூழலைப் பயன்படுத்தவும். PQ2_0/PTQ1_0 க்கு PrismML ஐத் தேர்ந்தெடுக்கவும்.",
  runnerLlamaMinus: "− GGUF மட்டும்; இணைநிலை ஸ்லாட்டுகளால் வரம்பு.",
  runnerVllmMinus: "− முதல் தொடக்கம் நீளம் (venv + தொகுப்பு); utilization படி VRAM ஒதுக்கம்; GGUF சோதனை நிலை.",
  runnerWhisperMinus: "− படியெடுத்தல் மட்டும், LLM அல்ல; முதல் தொடக்கத்தில் மாடல் பதிவிறக்கம்.",
  runnerMoonshine: "moonshine",
  runnerMoonshineBenefits: "CPU-வில் பேச்சு-to-உரை (Moonshine v2) — EN மாடல் 250M அளவுருக்களில் Whisper large-v3 துல்லியத்தை மிஞ்சும், CPU கோரில் நொடிக்குள்; GPU-கள் LLM-களுக்கு; மாடல் தானே பதிவிறக்கம்; health /health-இல்.",
  runnerMoonshineMinus: "− ரஷ்யன் இல்லை (RU-க்கு whisper); EN MIT, மற்ற மொழிகளுக்கு இலவச Moonshine Community License தேவை (பதிவு + பெயர்க்குறிப்பு, வருவாய் $1M/ஆண்டுக்குள்).",
  runnerTranscribe: "transcribe.cpp",
  runnerTranscribeBenefits: "ggml இயக்க நேரத்தில் GGUF இலிருந்து பேச்சை உரையாக்கல் — ஒரே பில்டில் GigaAM, Parakeet, Canary, Whisper உள்ளிட்டவை இயங்கும், எந்த மாதிரி இயங்கும் என்பதைப் பொதுத் தேர்வியில் நீங்கள் தேர்ந்தெடுக்கும் கோப்பே தீர்மானிக்கிறது. ரஷ்யத்துக்கான சிறந்த இலவச அடையாளங்காணி: GigaAM-v3 இன் WER ஏறத்தாழ 8%, whisper large-v3 இன் 21-25%; பெரிய-சிறிய எழுத்துகளும் நிறுத்தக் குறியீடுகளும் உண்டு; 260 MB கோப்பு 0.1 வினாடியில் ஏற்றப்படும்; health /health இல்.",
  runnerTranscribeMinus: "− தனியாகப் பில்டு தேவை (scripts/install-transcribe.sh); ஒவ்வொரு மாதிரிக்கும் ஒலிச் சாளரம் குறுகியது (GigaAM க்கு 25 வினாடிகள்), எனவே நீளமான பதிவுகள் அமைதியான இடத்தில் வெட்டப்பட்டு மீண்டும் இணைக்கப்படும்; மாதிரிகளின் உரிமங்கள் வேறுபடும் — GigaAM-v3 MIT, சில ASR எடைகள் CC-BY-NC.",
  audioWindowChipTitle: "இந்த மாதிரி பயிற்சி பெற்ற அதிகபட்ச ஒலி நீளம் — அதைவிட நீளமானவை அமைதியான இடத்தில் வெட்டப்பட்டு இணைக்கப்படும்.",
