  driverUpToDateTip: "களஞ்சியங்களில் புதியது எதுவும் இல்லை",
  driverUpdateTitle: "GPU இயக்கியைப் புதுப்பிக்கவா?",
  driverUpdateText: "இது {package} {version} ஐ நிறுவும். கணினி மறுதொடக்கம் செய்யப்படும் வரை கார்டுகள் தற்போதைய மாட்யூலிலேயே இயங்கிக்கொண்டிருக்கும் — மறுதொடக்கம் செய்யும் நேரம் உங்கள் முடிவே.",
  driverUpdateWarn: "மறுதொடக்கம் செய்யும் வரை புதிய செல்கள் தொடங்காது: புதிய நூலகங்கள் பழைய கர்னல் தொகுதியுடன் சந்திக்கின்றன. ஏற்கெனவே இயங்கும் செல்கள் தொடர்ந்து செயல்படுகின்றன.",
