  driverAutoCheck: "அட்டவணைப்படி புதிய இயக்கியைச் சரிபார்க்கவும்",
  driverAutoInstall: "…அதை தானாகவே நிறுவவும் (மறுதொடக்கம் இன்னும் உங்கள் கையில்)",
