  cellSourceStaleChip: "பழைய சர்வர்",
  cellSourceStaleTip: "இயங்கிக் கொண்டிருக்கும் ப்ராசஸ், கண்ட்ரோலர் வழங்கும் செல் சர்வரை விடப் பழையது. அதன் அருகிலுள்ள ஃபைல் ஏற்கனவே புதியது — அதைப் பயன்படுத்த செல்லை ரீஸ்டார்ட் செய்யுங்கள்.",
  runnerCustomMinus: "− கட்டளை மற்றும் health பாதை மட்டுமே தெரியும் — மாடல் பகுப்பாய்வு, நினைவக மதிப்பீடு, முன்னமைப்புகள் இல்லை.",
