  scoutAddConnect: "இணை",
  scoutAddHint: "மெஷினில் caravan-scout நிறுவவும் (அதன் களஞ்சியத்திலிருந்து ./install.sh), பிறகு அது காட்டும் முகவரியை உள்ளிடவும். ஏற்கெனவே இங்கு இணைக்கப்பட்டுள்ள ஸ்கவுட்டை மீண்டும் இணைப்பது இணைப்பைச் சோதிக்கும்.",
  scoutAddWorking: "{url} உடன் இணைக்கப்படுகிறது…",
  scoutAddDone: "இணைக்கப்பட்டது: {name} (ஸ்கவுட் {version}) — இது போர்டில் உள்ளது.",
  scoutAddEmpty: "மெஷினின் முகவரியை உள்ளிடவும்.",
  scoutFindButton: "🔍 தேடு",
  scoutFindTitle: "உள்ளூர் நெட்வொர்க்கில் caravan-scout-ஐத் தேடு",
  scoutFindNetworksPh: "ஸ்கேன் செய்ய வேண்டிய நெட்வொர்க்குகள் — எ.கா. 10.0.30.0/24; காலியாக இருந்தால்: இந்தக் கன்ட்ரோலரின் சொந்த நெட்வொர்க்",
  scoutFindRun: "ஸ்கேன் செய்",
  scoutFindOwn: "இந்தக் கன்ட்ரோலரின் நெட்வொர்க்",
  scoutFindWorking: "ஸ்கவுட்களைத் தேடுகிறது: {networks}…",
  scoutFindNone: "{networks} இல் எந்த ஸ்கவுட்டும் போர்ட் {port} இல் பதிலளிக்கவில்லை. அங்கே caravan-scout நிறுவப்பட்டுள்ளதா, மெஷினின் ஃபயர்வால் போர்ட் {port} வழியாக உள்ளே வர அனுமதிக்கிறதா?",
  scoutFindFound: "{networks} இல் ஸ்கவுட்கள்: {count}",
  scoutFindFree: "கிடைக்கும்",
  scoutFindHere: "ஏற்கெனவே போர்டில் உள்ளது",
  scoutFindTaken: "வேறொரு கேரவானில் இணைக்கப்பட்டுள்ளது: முதலில் அங்கே துண்டிக்கவும்",
  scoutFindConnect: "இணை",
  nodeDisconnectScout: "துண்டி",
  nodeDisconnectScoutTitle: "இந்த மெஷினின் ஸ்கவுட்டைத் துண்டிக்கவும்: இது இந்தக் கன்ட்ரோலரை மறந்துவிடும், மெஷின் போர்டிலிருந்து வெளியேறும்",
  dlgDisconnectScout: "“{name}”-இன் ஸ்கவுட்டைத் துண்டிக்கவா?\n\nஇது இந்தக் கன்ட்ரோலரை மறந்துவிடும், மெஷின் போர்டிலிருந்து வெளியேறும். அங்கு இயங்கும் செல்கள் தொடர்ந்து இயங்கும் — தேவையில்லை எனில் முதலில் அவற்றை நிறுத்தவும். மீண்டும் கொண்டுவர, “இயந்திரங்கள்” பகுதியில் மீண்டும் சேர்க்கவும்.",
  dlgForgetSilentScout: "“{name}”-ஐ மறக்கவா?\n\nஅதன் ஸ்கவுட் பதிலளிக்கவில்லை ({ago}). மெஷின் போர்டிலிருந்து வெளியேறும் — அதன் ஸ்கவுட் இணைந்த நிலையில் திரும்பினால் மீண்டும் வரும். இதை நிரந்தரமாக அகற்ற, அந்த மெஷினில் ./uninstall.sh இயக்கவும்.",
  scoutDisconnected: "{name}: ஸ்கவுட் துண்டிக்கப்பட்டது",
  scoutForgottenSilent: "{name} மறக்கப்பட்டது — அதன் ஸ்கவுட் பதிலளிக்கவில்லை",
  nodeScoutOld: "ஸ்கவுட் 1.x — புதுப்பிக்கவும்",
  nodeScoutOldTitle: "இந்த மெஷினின் ஸ்கவுட் 2.0-ஐ விட பழையது: இது இன்னும் மெஷினில் உள்ள ஏஜென்ட்களைப் புகாரளிக்கிறது, அதை கன்ட்ரோலர் இனி படிக்காது. இதைப் புதுப்பிக்கவும்: அதன் ஃபோல்டரில் git pull, பிறகு ./install.sh.",
