  cvTipModelQueue: "இந்த வரிசை மேலே உள்ள மாதிரிக்கு உரியது. உள்ளீட்டு கேபிளை இணைத்தால் இது தெரியும். முதன்மை இலக்கு எப்போதும் இந்த மாதிரிதான். மாற்று கேபிளை வேறு மாதிரி அல்லது கிளவுட் வழங்குநருடன் இணைக்கவும். கடைசி உள்ளீட்டு கேபிளை அகற்றினால் வரிசை மறையும்; அமைப்புகள் பாதுகாக்கப்படும்.",
