  cvTipOnErrorNode: "கோரிக்கைகள் MAIN வழியாகச் செல்கின்றன. அந்த அப்ஸ்ட்ரீம் தோல்வியடைந்தால் — இணைப்பு நிராகரிக்கப்பட்டது அல்லது ஏதேனும் HTTP பிழை — மேலும் இதுவரை எதுவும் வாடிக்கையாளரை அடையவில்லை எனில், அதே கோரிக்கை BACKUP வழியாக மீண்டும் இயக்கப்படும். இந்த முனை நினைவில் கொள்கிறது: சான்றுகள் இல்லாமல், ஒதுக்கீடு இல்லாமல், மாடல் இல்லாமல் அல்லது சேவையகப் பிழையுடன் பதிலளித்த ஒரு வெளியேறு வழி ஐந்து நிமிடங்களுக்குத் தவிர்க்கப்படும், மேலும் செயலற்ற ஒவ்வொரு வெளியேறு வழியும் ஒவ்வொரு ஐந்து நிமிடங்களுக்கும் மீண்டும் சரிபார்க்கப்படும்; அடுத்த கோரிக்கை எங்கு செல்கிறது என்பதை ▶ குறிக்கிறது. இது மிகைநிலை ஏற்பாடு, சுமை மேலாண்மை அல்ல: திறன் இதில் பங்கு வகிக்காது.",
