  restoreBuildText: "காப்பகப்படுத்தப்பட்ட llama-server பதிப்பு மீண்டும் இடத்தில் நகலெடுக்கப்பட்டு, குளோன் அதன் கமிட்டுக்கு மாற்றப்படும். இயங்கும் மாதிரி சர்வர்கள் மறுதொடக்கம் வரை தற்போதைய பைனரியில் இருக்கும்.",
  noArchivedBuilds: "இன்னும் காப்பக பதிப்புகள் இல்லை — ஒவ்வொரு வெற்றிகரமான புதுப்பிப்பும் தானாக ஒன்றைக் காப்பகப்படுத்தும் (கடைசி 5 வைக்கப்படும்).",
  restoreBuildRecovery: "இந்த பதிப்பும் சிக்கல் தந்தால்: மாற்றப்படும் பதிப்பு காப்பகத்தில் இருக்கும் (அதே வழியில் மீட்டமைக்கலாம்), எந்த வெளியீட்டையும் Update Build மூலம் மூலத்திலிருந்து மீண்டும் கட்டலாம், இறுதி வழியாக அதே restore ssh வழியாகவும் இயங்கும்: bash scripts/install-llama.sh --restore <id>.",
  restoreBuildRecoveryHost: "இந்த பதிப்பும் சிக்கல் தந்தால்: மாற்றப்படும் பதிப்பு இயந்திரத்தின் காப்பகத்தில் இருக்கும் (அதே வழியில் மீட்டமைக்கலாம்), இயந்திர அட்டையிலுள்ள ⇪ மூலம் மீண்டும் கட்டலாம், இறுதி வழியாக அதே restore ssh வழியாக scout கோப்புறையில் இயங்கும்: bash scripts/update-llama.sh --restore <id>.",
