  vramEstChipTitle: "வட்டில் உள்ள மாடல் கோப்பின் அளவிலிருந்து மதிப்பீடு — உண்மையான VRAM இல் சூழல்/KV கூடுதலாகும்",
  vramPlanChipTitle: "RTX 5090-இல் அளவிடப்பட்டது: இந்த சேவையகத்தின் இயந்திரம் இயங்கும்போது, மாடல் கோப்புகளின் அளவு எதுவாக இருந்தாலும், ஏறக்குறைய இவ்வளவு VRAM பிடிக்கும்",
  cellRamTitle: "இந்த செல்லின் செயல்முறைகள் வைத்திருக்கும் RAM (நேரடி): அவற்றின் குடியிருப்பு அளவு — சேவையகமும் அது தொடங்கிய அனைத்தும். நினைவக வரைபடம் மூலம் படித்த மாதிரி கோப்புகளும் இதில் அடங்கும்: CPU செல்லின் எடைகள் இதில் உள்ளன, இரு செல்கள் வரைபடமிடும் கோப்பு இரண்டிலும் கணக்கிடப்படும்.",
  cellMemUnknownTitle: "தெரிவிக்கப்படவில்லை: இந்த இயந்திரத்தின் scout (2.35-க்கு முந்தையது), அட்டைகளின் வாசிப்பு அல்லது இயந்திரம் இதைச் சொல்லவில்லை. பூஜ்யம் அல்ல, கோடு — பூஜ்யம் என்றால் செல் எதுவும் வைத்திருக்கவில்லை என்று பொருள்.",
  cellRamEstChipTitle: "வட்டில் உள்ள மாதிரி கோப்பின் அளவிலிருந்து மதிப்பீடு — CPU செல் தன் எடைகளை RAM-இல் வைக்கிறது, சூழல் அதனுடன் சேரும்.",
