  mdlFreshNewer: "இதே பெயரில் Hugging Face-இல் வேறு கோப்பு உள்ளது — நம்முடையது: {ours}; HF-இல்: {theirs}",
  mdlFreshUnknown: "Hugging Face-இல் ஒப்பிட எதுவும் இல்லை",
  mdlFreshGroup: "இங்கு {n} கோப்பு(கள்) Hugging Face இலிருந்து வேறுபடுகின்றன",
  mdlStagedGetTip: "இந்தக் கோப்பின் மேல் புதிய பதிப்பைப் பதிவிறக்கவும். இயங்கிக்கொண்டிருக்கும் செல், மறுதொடக்கம் செய்யப்படும் வரை தான் ஏற்றிய எடைகளையே தொடர்ந்து பயன்படுத்தும்.",
  mdlStagedPrevTip: "முந்தைய பதிப்பு, Hugging Face-இல் இனி இல்லாததால் பாதுகாக்கப்பட்டுள்ளது. மீட்டமைத்தால் இது திரும்பப் பெறப்பட்டு, புதிய கோப்பு நீக்கப்படும் — அந்தக் கோப்பை எப்போது வேண்டுமானாலும் மீண்டும் பதிவிறக்கலாம்.",
  mdlStagedGetTitle: "புதிய பதிப்பைப் பதிவிறக்கவா?",
  mdlStagedGetConfirm: "{name} Hugging Face இலிருந்து ({size}) இந்த வட்டில் உள்ள கோப்பின் மேல் பதிவிறக்கப்படும்.",
  mdlStagedGetKept: "தற்போதைய பதிப்பு முந்தையதாகப் பாதுகாக்கப்படும், எனவே அதை மீட்டமைக்கலாம்.",
  mdlStagedGetLost: "தற்போதைய பதிப்பு பாதுகாக்கப்படாது: புதியது வந்ததும், அதை மீட்டமைக்க முடியாது.",
  mdlStagedPrevTitle: "முந்தைய பதிப்பை மீட்டமைக்கவா?",
  mdlStagedPrevConfirm: "{name}: பாதுகாக்கப்பட்டுள்ள முந்தைய பதிப்பு இந்த வட்டில் உள்ள கோப்பிற்குப் பதிலாக அமையும், புதிய கோப்பு நீக்கப்படும். அதை Hugging Face இலிருந்து மீண்டும் பதிவிறக்கலாம்.",
  mdlFreshAutoTip: "டிஸ்க்கில் உள்ளதை கீழே உள்ள நேரத்தில் Hugging Face உடன் ஒப்பிடுகிறது. பார்ப்பது மட்டும் எதையும் பதிவிறக்காது.",
  mdlFreshGetTip: "புதிய பில்ட் செயல்பாட்டில் உள்ள கோப்பின் மேல் எழுதப்படும், எனவே கீழே அதை வைத்திருக்காவிட்டால் பழையது இல்லாமல் போகும். இயங்கும் ஒரு செல், அதை மறுதொடக்கம் செய்யும் வரை ஏற்கெனவே ஏற்றிய வெயிட்டுகளை வைத்திருக்கும்.",
  mdlFreshAtLabel: "க்கு",
  mdlFreshAtTip: "தினசரி சரிபார்ப்பின் உள்ளூர் நேரம். அந்த நேரத்தில் கன்ட்ரோலர் அணைந்திருந்தால், அது அடுத்த வாய்ப்பில் சரிபார்க்கும்.",
  mdlFreshKeepLabel: "முந்தைய பதிப்பைப் பாதுகாக்கவும் (வட்டில் அதன் அளவுக்கான இடத்தை எடுத்துக்கொள்ளும்)",
  cellModelDiskNewerChip: "கோப்பு புதுப்பிக்கப்பட்டது",
  cellModelDiskNewerTip: "வட்டில் உள்ள மாதிரிக் கோப்பு, இந்தச் செல் ஏற்றியதை விட புதியது. செல்லுக்குள் எதுவும் மாறவில்லை — அது ஏற்கெனவே ஏற்றிய எடைகளையே தொடர்ந்து வழங்குகிறது. புதிய கோப்பைப் பயன்படுத்த செல்லை மறுதொடக்கம் செய்யவும்.",
