  cellModelStaleTip: "Hugging Face இப்போது இந்த மாடலின் பெயரில் வேறு கோப்பை வெளியிடுகிறது — இந்த நகல் பதிவிறக்கப்பட்ட பிறகு ஆசிரியர் அதை மீண்டும் வெளியிட்டார். இங்கே எதுவும் மாறவில்லை: செல் இன்னும் தன்னிடம் உள்ள கோப்பையே இயக்குகிறது. HF பக்கம் இரண்டு அளவுகளையும் தேதிகளையும் காட்டுகிறது.",
