  moveConfirm: "{count} கோப்பு(கள்) ({size}) {name} க்கு நகர்த்தவா?\n\nஒவ்வொரு கோப்பும் நகலெடுக்கப்பட்டு, நூலகத்திலிருந்து மீண்டும் படிக்கப்பட்டு, மூலக் கோப்புடன் ஒப்பிடப்படுகிறது. அவை பொருந்தினால் மட்டுமே இந்த வட்டிலுள்ள நகல் நீக்கப்படும். இணைப்பு துண்டிக்கப்பட்டால், நகர்த்துதல் காத்திருந்து தொடரும்: சரிபார்ப்பதற்கு முன் எதுவும் நீக்கப்படாது.",
