  splitHintLayer: "அடுக்குகள் அட்டைகளுக்குப் பங்கிடப்படும், அட்டைகள் முறைவைத்துக் கணக்கிடும்: நினைவகம் கூடும், ஆனால் ஒரு கோரிக்கை வேகமாகாது.",
  splitHintParallel: "ஒவ்வொரு எடையும் அட்டைகளுக்கு இடையே வெட்டப்பட்டு, அவை ஒரே நேரத்தில் கணக்கிடும். ஒரு கோரிக்கை வேகமாகும், ஆனால் அட்டைகளுக்கு இடையிலான இணைப்பு வேகமாக இருக்க வேண்டும் — சாதாரண PCIe-இல் அடுக்குப் பிரிப்பை விடவும் மெதுவாகக்கூட முடியும்.",
  splitHintRow: "ஒவ்வொரு எடையும் வரிசைகளின்படி அட்டைகளுக்கிடையே வெட்டப்படுகிறது, அட்டைகள் ஒரே நேரத்தில் வேலை செய்கின்றன. 2026 ஜூலை முதல் உள்ள llama.cpp கட்டமைப்புகளில் NVIDIA அட்டைகளுக்கு இந்த முறை இல்லை (மூலத் திட்டத்தில் நீக்கப்பட்டது): அப்போது செல் “split buffers” உடன் நின்றுவிடும். அங்கே “{layer}” அல்லது “{tensor}” தேர்ந்தெடுக்கவும்.",
