  routeModelLockedTip: "பூட்டப்பட்டது: போர்ட், இங்கே எழுதப்பட்ட பெயரில் மாடலை அறிவிக்கிறது. திறக்க கிளிக் செய்யவும் — பிறகு அது மாடல் தானே தெரிவிக்கும் பெயரை அறிவிக்கும், மேலும் எழுதப்பட்ட பெயர் அப்படியே இருக்கும், அது நீங்கள் மீண்டும் பூட்டும்போது பயன்படும்.",
