  dlgRouteModel: "இந்த போர்ட் மாதிரியை அறிவிக்கும் பெயர். வெறுமை என்றால் அப்ஸ்ட்ரீமின் பெயர். கிளையன்ட் /v1/models-இல் தன் id-ஐத் தேடும்; கிடைக்காவிட்டால் உள்ளமைந்த இயல்பை எடுக்கும்.",
